BEGIN;
UPDATE public.ta_lessons SET title_pl='Wiklina i inne surowce', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Rozróżnianie pędów wierzby, rattanu, trzciny i łyka"},{"heading":"Materiałoznawstwo i proces","text":"Wiklina jest młodym pędem wierzby; rattan pochodzi z palm pnących, a trzcina ma inną strukturę i sztywność. Nie zastępuj surowców 1:1: o doborze decydują średnica, długość, sprężystość, wilgotność i kierunek włókien."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Porównaj wyniki na co najmniej trzech próbkach; zapisuj średnicę, rozstaw, odkształcenia i liczbę defektów."},{"heading":"Ćwiczenie praktyczne","text":"Zmierz średnicę dziesięciu pędów suwmiarką; odrzuć pędy z pęknięciami i zapisz rozrzut wymiarów."}],"learning":{"intro":"Wiklina jest młodym pędem wierzby; rattan pochodzi z palm pnących, a trzcina ma inną strukturę i sztywność. Nie zastępuj surowców 1:1: o doborze decydują średnica, długość, sprężystość, wilgotność i kierunek włókien.","task":"Zmierz średnicę dziesięciu pędów suwmiarką; odrzuć pędy z pęknięciami i zapisz rozrzut wymiarów.","question":"Masz partię pędów o średnicach 3–7 mm. Jak dobrać je do równomiernej ścianki?","options":["Posegregować według średnicy i elastyczności, cienkie wykorzystać do ciasnych łuków.","Wymieszać losowo bez kontroli grubości.","Użyć wyłącznie najgrubszych do każdego zagięcia.","Przesuszyć wszystkie pędy przed ciasnym gięciem."],"correct":0,"feedback":["Tak. Posegregować według średnicy i elastyczności, cienkie wykorzystać do ciasnych łuków. Uzasadnij wybór obserwacją lub obliczeniem.","Nie. Wymieszać losowo bez kontroli grubości. nie rozwiązuje wskazanego problemu. Wróć do zasady: Posegregować według średnicy i elastyczności, cienkie wykorzystać do ciasnych łuków.","Nie. Użyć wyłącznie najgrubszych do każdego zagięcia. nie rozwiązuje wskazanego problemu. Wróć do zasady: Posegregować według średnicy i elastyczności, cienkie wykorzystać do ciasnych łuków.","Nie. Przesuszyć wszystkie pędy przed ciasnym gięciem. nie rozwiązuje wskazanego problemu. Wróć do zasady: Posegregować według średnicy i elastyczności, cienkie wykorzystać do ciasnych łuków."],"explanation":"Posegregować według średnicy i elastyczności, cienkie wykorzystać do ciasnych łuków.","example":"Zmierz średnicę dziesięciu pędów suwmiarką; odrzuć pędy z pęknięciami i zapisz rozrzut wymiarów.","quiz_version":9},"curiosity":"W plecionkarstwie pozornie drobna zmiana wilgotności lub grubości pędu może zmienić promień gięcia i geometrię całego wyrobu.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=0;
UPDATE public.ta_lessons SET title_pl='Przygotowanie i nawilżanie', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Kontrolowana elastyczność bez łamania włókien"},{"heading":"Materiałoznawstwo i proces","text":"Suche pędy mogą pękać; moczenie przywraca elastyczność, lecz czas zależy od gatunku, grubości, temperatury i stanu surowca. Testuj małą próbkę, zamiast przyjmować jeden uniwersalny czas. Mokry materiał po pracy należy prawidłowo dosuszyć, aby ograniczyć pleśń."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Porównaj wyniki na co najmniej trzech próbkach; zapisuj średnicę, rozstaw, odkształcenia i liczbę defektów."},{"heading":"Ćwiczenie praktyczne","text":"Zrób próbę gięcia trzech pędów o tej samej średnicy w różnych stanach nawilżenia; notuj promień pierwszego pęknięcia."}],"learning":{"intro":"Suche pędy mogą pękać; moczenie przywraca elastyczność, lecz czas zależy od gatunku, grubości, temperatury i stanu surowca. Testuj małą próbkę, zamiast przyjmować jeden uniwersalny czas. Mokry materiał po pracy należy prawidłowo dosuszyć, aby ograniczyć pleśń.","task":"Zrób próbę gięcia trzech pędów o tej samej średnicy w różnych stanach nawilżenia; notuj promień pierwszego pęknięcia.","question":"Po moczeniu pędy nadal pękają przy małym promieniu. Co sprawdzić najpierw?","options":["Zwiększyć siłę, aż pęd się podda.","Zbadać gatunek, przekrój, wilgotność i promień gięcia na próbce.","Skleić wszystkie pęknięcia przed wyplataniem.","Pracować szybciej, by ukryć defekt."],"correct":1,"feedback":["Nie. Zwiększyć siłę, aż pęd się podda. nie rozwiązuje wskazanego problemu. Wróć do zasady: Zbadać gatunek, przekrój, wilgotność i promień gięcia na próbce.","Tak. Zbadać gatunek, przekrój, wilgotność i promień gięcia na próbce. Uzasadnij wybór obserwacją lub obliczeniem.","Nie. Skleić wszystkie pęknięcia przed wyplataniem. nie rozwiązuje wskazanego problemu. Wróć do zasady: Zbadać gatunek, przekrój, wilgotność i promień gięcia na próbce.","Nie. Pracować szybciej, by ukryć defekt. nie rozwiązuje wskazanego problemu. Wróć do zasady: Zbadać gatunek, przekrój, wilgotność i promień gięcia na próbce."],"explanation":"Zbadać gatunek, przekrój, wilgotność i promień gięcia na próbce.","example":"Zrób próbę gięcia trzech pędów o tej samej średnicy w różnych stanach nawilżenia; notuj promień pierwszego pęknięcia.","quiz_version":9},"curiosity":"W plecionkarstwie pozornie drobna zmiana wilgotności lub grubości pędu może zmienić promień gięcia i geometrię całego wyrobu.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=1;
UPDATE public.ta_lessons SET title_pl='Dno kosza', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Krzyżak i promieniste rozłożenie osnowy"},{"heading":"Materiałoznawstwo i proces","text":"Dno okrągłego kosza rozpoczyna się od krzyżaka z prętów konstrukcyjnych. Po rozdzieleniu promieni oplata się je stopniowo, kontrolując rozstaw i płaskość. Gdy rozstaw jest nierówny, kolejne okrążenia utrwalą błąd."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Rozstaw 12 promieni: 360°/12 = 30°."},{"heading":"Ćwiczenie praktyczne","text":"Na kartonie narysuj 12 promieni co 30° i przeprowadź sznurkiem symulację splotu dna."}],"learning":{"intro":"Dno okrągłego kosza rozpoczyna się od krzyżaka z prętów konstrukcyjnych. Po rozdzieleniu promieni oplata się je stopniowo, kontrolując rozstaw i płaskość. Gdy rozstaw jest nierówny, kolejne okrążenia utrwalą błąd.","task":"Na kartonie narysuj 12 promieni co 30° i przeprowadź sznurkiem symulację splotu dna.","question":"Dno ma 12 promieni. Jaki jest kąt pomiędzy równomiernie rozmieszczonymi promieniami?","options":["15°","24°","30°","45°"],"correct":2,"feedback":["Nie. 15° nie rozwiązuje wskazanego problemu. Wróć do zasady: 30°","Nie. 24° nie rozwiązuje wskazanego problemu. Wróć do zasady: 30°","Tak. 30° Uzasadnij wybór obserwacją lub obliczeniem.","Nie. 45° nie rozwiązuje wskazanego problemu. Wróć do zasady: 30°"],"explanation":"30°","example":"Na kartonie narysuj 12 promieni co 30° i przeprowadź sznurkiem symulację splotu dna.","quiz_version":9},"curiosity":"W plecionkarstwie pozornie drobna zmiana wilgotności lub grubości pędu może zmienić promień gięcia i geometrię całego wyrobu.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=2;
UPDATE public.ta_lessons SET title_pl='Osnowa i splot prosty', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Przeplot nad–pod oraz kontrola napięcia"},{"heading":"Materiałoznawstwo i proces","text":"Osnowa tworzy szkielet ścianki, a wątek przechodzi naprzemiennie nad i pod prętami. Przy parzystej liczbie stojaków i ciągłym jednym wątku układ może wymagać korekty sposobu prowadzenia, by nie powtarzać identycznego przejścia na kolejnych okrążeniach. Nie ściągaj wątku zbyt mocno."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Porównaj wyniki na co najmniej trzech próbkach; zapisuj średnicę, rozstaw, odkształcenia i liczbę defektów."},{"heading":"Ćwiczenie praktyczne","text":"Ułóż na stole 9 pionowych pasków papieru i przepleć poziome paski, utrzymując stałą szerokość odstępów."}],"learning":{"intro":"Osnowa tworzy szkielet ścianki, a wątek przechodzi naprzemiennie nad i pod prętami. Przy parzystej liczbie stojaków i ciągłym jednym wątku układ może wymagać korekty sposobu prowadzenia, by nie powtarzać identycznego przejścia na kolejnych okrążeniach. Nie ściągaj wątku zbyt mocno.","task":"Ułóż na stole 9 pionowych pasków papieru i przepleć poziome paski, utrzymując stałą szerokość odstępów.","question":"Ścianka zwęża się mimo prostego szablonu. Co najprawdopodobniej poprawić?","options":["Mocniej docisnąć każdy wątek.","Zwiększyć wilgotność gotowego kosza przez zamknięcie w folii.","Usunąć część stojaków bez przeliczenia rozstawu.","Zmniejszyć napięcie wątku i kontrolować pion stojaków."],"correct":3,"feedback":["Nie. Mocniej docisnąć każdy wątek. nie rozwiązuje wskazanego problemu. Wróć do zasady: Zmniejszyć napięcie wątku i kontrolować pion stojaków.","Nie. Zwiększyć wilgotność gotowego kosza przez zamknięcie w folii. nie rozwiązuje wskazanego problemu. Wróć do zasady: Zmniejszyć napięcie wątku i kontrolować pion stojaków.","Nie. Usunąć część stojaków bez przeliczenia rozstawu. nie rozwiązuje wskazanego problemu. Wróć do zasady: Zmniejszyć napięcie wątku i kontrolować pion stojaków.","Tak. Zmniejszyć napięcie wątku i kontrolować pion stojaków. Uzasadnij wybór obserwacją lub obliczeniem."],"explanation":"Zmniejszyć napięcie wątku i kontrolować pion stojaków.","example":"Ułóż na stole 9 pionowych pasków papieru i przepleć poziome paski, utrzymując stałą szerokość odstępów.","quiz_version":9},"curiosity":"W plecionkarstwie pozornie drobna zmiana wilgotności lub grubości pędu może zmienić promień gięcia i geometrię całego wyrobu.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=3;
UPDATE public.ta_lessons SET title_pl='Splot dwuprętowy i trzyprętowy', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Wzmacnianie i wyrównywanie ścianek"},{"heading":"Materiałoznawstwo i proces","text":"Splot dwuprętowy (twining) skręca dwa wątki wokół stojaków; splot trzyprętowy pozwala budować zwarty pas i bywa używany przy przejściach konstrukcyjnych. Wybór zależy od geometrii, średnicy surowca i wymaganej sztywności. Równy splot nie zastąpi dobrego rozstawu osnowy."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Porównaj wyniki na co najmniej trzech próbkach; zapisuj średnicę, rozstaw, odkształcenia i liczbę defektów."},{"heading":"Ćwiczenie praktyczne","text":"Na modelu z papierowych rurek wykonaj dwa rzędy przeplotu dwoma wątkami, oznacz ich kolejność kolorami."}],"learning":{"intro":"Splot dwuprętowy (twining) skręca dwa wątki wokół stojaków; splot trzyprętowy pozwala budować zwarty pas i bywa używany przy przejściach konstrukcyjnych. Wybór zależy od geometrii, średnicy surowca i wymaganej sztywności. Równy splot nie zastąpi dobrego rozstawu osnowy.","task":"Na modelu z papierowych rurek wykonaj dwa rzędy przeplotu dwoma wątkami, oznacz ich kolejność kolorami.","question":"Dlaczego przy zmianie splotu warto wykonać próbę na fragmencie modelu?","options":["Aby sprawdzić kolejność przejść, napięcie i wygląd bez deformacji całego kosza.","Aby uniknąć pomiaru rozstawu stojaków.","Aby zastąpić całą konstrukcję klejem.","Ponieważ każdy splot ma identyczną wytrzymałość."],"correct":0,"feedback":["Tak. Aby sprawdzić kolejność przejść, napięcie i wygląd bez deformacji całego kosza. Uzasadnij wybór obserwacją lub obliczeniem.","Nie. Aby uniknąć pomiaru rozstawu stojaków. nie rozwiązuje wskazanego problemu. Wróć do zasady: Aby sprawdzić kolejność przejść, napięcie i wygląd bez deformacji całego kosza.","Nie. Aby zastąpić całą konstrukcję klejem. nie rozwiązuje wskazanego problemu. Wróć do zasady: Aby sprawdzić kolejność przejść, napięcie i wygląd bez deformacji całego kosza.","Nie. Ponieważ każdy splot ma identyczną wytrzymałość. nie rozwiązuje wskazanego problemu. Wróć do zasady: Aby sprawdzić kolejność przejść, napięcie i wygląd bez deformacji całego kosza."],"explanation":"Aby sprawdzić kolejność przejść, napięcie i wygląd bez deformacji całego kosza.","example":"Na modelu z papierowych rurek wykonaj dwa rzędy przeplotu dwoma wątkami, oznacz ich kolejność kolorami.","quiz_version":9},"curiosity":"W plecionkarstwie pozornie drobna zmiana wilgotności lub grubości pędu może zmienić promień gięcia i geometrię całego wyrobu.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=4;
UPDATE public.ta_lessons SET title_pl='Kształt i obliczanie materiału', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Obwód, wysokość i zapas roboczy"},{"heading":"Materiałoznawstwo i proces","text":"Dla kosza cylindrycznego obwód wynosi π·D. Przy średnicy 30 cm to około 94,2 cm na okrążenie; 20 okrążeń wymaga teoretycznie około 18,85 m wątku, jeszcze bez zapasu na przeplot, połączenia i straty. Realne zużycie wyznacza próba technologiczna."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Obwód: π·D; 20 × π × 0,30 m ≈ 18,85 m przed doliczeniem strat."},{"heading":"Ćwiczenie praktyczne","text":"Policz teoretyczną długość dla średnicy 24 cm i 15 okrążeń; dodaj osobno założony zapas 15%."}],"learning":{"intro":"Dla kosza cylindrycznego obwód wynosi π·D. Przy średnicy 30 cm to około 94,2 cm na okrążenie; 20 okrążeń wymaga teoretycznie około 18,85 m wątku, jeszcze bez zapasu na przeplot, połączenia i straty. Realne zużycie wyznacza próba technologiczna.","task":"Policz teoretyczną długość dla średnicy 24 cm i 15 okrążeń; dodaj osobno założony zapas 15%.","question":"Ile wynosi obwód koła o średnicy 30 cm?","options":["30 cm","Około 94,2 cm","Około 188,5 cm","Około 9,4 cm"],"correct":1,"feedback":["Nie. 30 cm nie rozwiązuje wskazanego problemu. Wróć do zasady: Około 94,2 cm","Tak. Około 94,2 cm Uzasadnij wybór obserwacją lub obliczeniem.","Nie. Około 188,5 cm nie rozwiązuje wskazanego problemu. Wróć do zasady: Około 94,2 cm","Nie. Około 9,4 cm nie rozwiązuje wskazanego problemu. Wróć do zasady: Około 94,2 cm"],"explanation":"Około 94,2 cm","example":"Policz teoretyczną długość dla średnicy 24 cm i 15 okrążeń; dodaj osobno założony zapas 15%.","quiz_version":9},"curiosity":"Dla tej samej liczby okrążeń zwiększenie średnicy o 10% zwiększa teoretyczne zużycie wątku również o 10%.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=5;
UPDATE public.ta_lessons SET title_pl='Zakończenie brzegu i uchwyt', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Bezpieczne końcówki i ciągłość przenoszenia siły"},{"heading":"Materiałoznawstwo i proces","text":"Wykończenie brzegu blokuje stojaki i eliminuje ostre końce. Uchwyt powinien przenosić obciążenie przez konstrukcję, a nie jedynie przez ozdobny oplot. Należy sprawdzić symetrię mocowania i stopniowo testować obciążenie na próbkach, bez deklarowania nośności bez badań."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Porównaj wyniki na co najmniej trzech próbkach; zapisuj średnicę, rozstaw, odkształcenia i liczbę defektów."},{"heading":"Ćwiczenie praktyczne","text":"Na modelu papierowym zaznacz dwie symetryczne strefy mocowania uchwytu i wskaż drogę przenoszenia siły."}],"learning":{"intro":"Wykończenie brzegu blokuje stojaki i eliminuje ostre końce. Uchwyt powinien przenosić obciążenie przez konstrukcję, a nie jedynie przez ozdobny oplot. Należy sprawdzić symetrię mocowania i stopniowo testować obciążenie na próbkach, bez deklarowania nośności bez badań.","task":"Na modelu papierowym zaznacz dwie symetryczne strefy mocowania uchwytu i wskaż drogę przenoszenia siły.","question":"Uchwyt odrywa się przy niewielkim obciążeniu. Które rozwiązanie jest właściwe?","options":["Dodać samą farbę na połączenie.","Zignorować uszkodzenie, jeśli kosz wygląda dobrze.","Przeprojektować zakotwienie w osnowie i ponownie przetestować.","Zwiększyć masę ładunku, aby docisnąć uchwyt."],"correct":2,"feedback":["Nie. Dodać samą farbę na połączenie. nie rozwiązuje wskazanego problemu. Wróć do zasady: Przeprojektować zakotwienie w osnowie i ponownie przetestować.","Nie. Zignorować uszkodzenie, jeśli kosz wygląda dobrze. nie rozwiązuje wskazanego problemu. Wróć do zasady: Przeprojektować zakotwienie w osnowie i ponownie przetestować.","Tak. Przeprojektować zakotwienie w osnowie i ponownie przetestować. Uzasadnij wybór obserwacją lub obliczeniem.","Nie. Zwiększyć masę ładunku, aby docisnąć uchwyt. nie rozwiązuje wskazanego problemu. Wróć do zasady: Przeprojektować zakotwienie w osnowie i ponownie przetestować."],"explanation":"Przeprojektować zakotwienie w osnowie i ponownie przetestować.","example":"Na modelu papierowym zaznacz dwie symetryczne strefy mocowania uchwytu i wskaż drogę przenoszenia siły.","quiz_version":9},"curiosity":"W plecionkarstwie pozornie drobna zmiana wilgotności lub grubości pędu może zmienić promień gięcia i geometrię całego wyrobu.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=6;
UPDATE public.ta_lessons SET title_pl='Suszenie, kontrola i projekt', material=material || '{"curriculum_revision":9,"review_status":"review_needed","sections":[{"heading":"Co poznasz","text":"Wady, odbiór jakości i kosztorys"},{"heading":"Materiałoznawstwo i proces","text":"Gotowy kosz oceniaj pod kątem stabilności dna, równomierności ścianek, wystających końcówek, uszkodzeń włókien i wilgoci. Susz w przewiewie bez gwałtownego przegrzewania. Koszt jednostkowy obejmuje materiał, odpady, czas pracy, narzędzia i koszty pośrednie; nie myl ceny sprzedaży z kosztem."},{"heading":"Zastosowanie w warsztacie","text":"Sprawdź materiał na próbce, zaplanuj kolejność operacji i kontroluj geometrię. Nie używaj ostrych narzędzi bez przeszkolenia; na początku ćwicz na papierze i sznurku."},{"heading":"Obliczenia i kontrola","text":"Porównaj wyniki na co najmniej trzech próbkach; zapisuj średnicę, rozstaw, odkształcenia i liczbę defektów."},{"heading":"Ćwiczenie praktyczne","text":"Zaprojektuj kosz o średnicy 25 cm i wysokości 20 cm; narysuj dno, osnowę i brzeg, oblicz obwód, zapisz kontrolę pięciu wad i budżet."}],"learning":{"intro":"Gotowy kosz oceniaj pod kątem stabilności dna, równomierności ścianek, wystających końcówek, uszkodzeń włókien i wilgoci. Susz w przewiewie bez gwałtownego przegrzewania. Koszt jednostkowy obejmuje materiał, odpady, czas pracy, narzędzia i koszty pośrednie; nie myl ceny sprzedaży z kosztem.","task":"Zaprojektuj kosz o średnicy 25 cm i wysokości 20 cm; narysuj dno, osnowę i brzeg, oblicz obwód, zapisz kontrolę pięciu wad i budżet.","question":"Materiał kosztuje 28 zł, robocizna 72 zł, pozostałe koszty 20 zł. Ile wynosi koszt wykonania?","options":["100 zł","92 zł","120 zł","140 zł"],"correct":2,"feedback":["Nie. 100 zł nie rozwiązuje wskazanego problemu. Wróć do zasady: 120 zł","Nie. 92 zł nie rozwiązuje wskazanego problemu. Wróć do zasady: 120 zł","Tak. 120 zł Uzasadnij wybór obserwacją lub obliczeniem.","Nie. 140 zł nie rozwiązuje wskazanego problemu. Wróć do zasady: 120 zł"],"explanation":"120 zł","example":"Zaprojektuj kosz o średnicy 25 cm i wysokości 20 cm; narysuj dno, osnowę i brzeg, oblicz obwód, zapisz kontrolę pięciu wad i budżet.","quiz_version":9},"curiosity":"W plecionkarstwie pozornie drobna zmiana wilgotności lub grubości pędu może zmienić promień gięcia i geometrię całego wyrobu.","editorial_status":"review_needed","references":[{"label":"Materiały dydaktyczne do weryfikacji specjalistycznej","url":"https://www.basketmakersassociation.org.uk/"}]}'::jsonb, updated_at=now() WHERE course_slug='plecionkarz' AND lesson_no=7;
